#include <stdio.h>

void double_values(int values[], int count)
{
    for (int i = 0; i < count; i++) {
        values[i] *= 2;
    }
}

int main(void)
{
    int a[] = {3, 7};
    double_values(a, 2);
    printf("%d\n", a[1]);
    return 0;
}

#include <stdio.h>

int array_sum(const int values[], int count)
{
    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    return sum;
}

int main(void)
{
    int a[1] = {99};
    printf("%d\n", array_sum(a, 0));
    return 0;
}

#include <stdio.h>

int *pair(int start)
{
    static int result[2];
    result[0] = start;
    result[1] = start + 1;
    return result;
}

int main(void)
{
    int *first = pair(2);
    pair(8);
    printf("%d\n", first[0]);
    return 0;
}

